class Mobile_api_error extends RuntimeException {
    public $status; public $apiCode;
    public function __construct($message,$status=422,$code='VALIDATION'){parent::__construct($message);$this->status=$status;$this->apiCode=$code;}
}
class Mobile_service extends CI_Model
{
    private $catalogModel;
    private $roles=array('owner','super_admin','admin','manager','finance','maintenance','viewer');
    public function __construct(){parent::__construct();$this->load->model(array('Operations_model','Master_model','Lifecycle_model','Auth_model'));require_once dirname(dirname(dirname(__DIR__))).'/landing/application/models/Landing_model.php';$this->catalogModel=new Landing_model();}
    public function sanitize($value,$parentKey='')
    {
        if(!is_array($value))return Mobile_public_data::media($value);
        $out=array();
        foreach($value as $k=>$v){
            // Password input metadata is safe; stored or submitted credential values are never returned.
            if($k==='password'&&$parentKey==='fields'&&is_array($v)&&($v['type']??'')==='password'){
                $out[$k]=array('label'=>'Password baru (10-72 karakter)','type'=>'password','required'=>FALSE);
                continue;
            }
            if(in_array($k,array('password','password_hash','token_hash','access_hash','storage_name','file_path','stored_filename','ocr_json'),TRUE))continue;
            $out[$k]=$this->sanitize($v,(string)$k);
        }
        if(isset($value['kind'],$value['id'])&&in_array($value['kind'],array('ktp','marriage','scan','photo','rent_proof','refund_proof','penalty_proof'),TRUE)){$out['file_kind']='lifecycle';$out['file_id']=(int)$value['id'];}
        elseif(isset($value['document_type'],$value['document_title'],$value['id'])){$out['file_kind']='document';$out['file_id']=(int)$value['id'];}
        elseif(isset($value['stored_filename'],$value['id'])){$out['file_kind']='payment-proof';$out['file_id']=(int)$value['id'];}
        return $out;
    }
    private function throttle($kind){$path=rtrim($this->config->item('sess_save_path'),'/\\').'/gh_mobile_'.hash('sha256',$this->db->database.$kind.$this->input->ip_address()).'.json';$h=@fopen($path,'c+');if(!$h||!flock($h,LOCK_EX)){if($h)fclose($h);throw new Mobile_api_error('Login sementara tidak tersedia.',503,'AUTH_BUSY');}$v=json_decode(stream_get_contents($h),TRUE);if(!is_array($v)||($v['until']??0)<=time())$v=array('until'=>time()+300,'count'=>0);$v['count']++;rewind($h);ftruncate($h,0);fwrite($h,json_encode($v));fflush($h);flock($h,LOCK_UN);fclose($h);if($v['count']>20)throw new Mobile_api_error('Terlalu banyak percobaan. Tunggu lima menit.',429,'RATE_LIMIT');}
    public function issue($kind,$id,$name,$role,$device=''){$token=bin2hex(random_bytes(32));$expires=date('Y-m-d H:i:s',time()+($kind==='admin'?43200:($kind==='payment'?1800:604800)));if(!$this->db->insert('gh_mobile_tokens',array('token_hash'=>hash('sha256',$token),'subject_kind'=>$kind,'subject_id'=>$id,'expires_at'=>$expires,'device_label'=>substr((string)$device,0,120))))throw new Mobile_api_error('Token belum dapat dibuat.',503,'AUTH_BUSY');return array('token'=>$token,'expires_at'=>$expires,'user'=>array('kind'=>$kind,'id'=>(int)$id,'name'=>$name,'role'=>$role));}
    public function login($kind,$p)
    {
        $this->throttle('login_'.$kind);
        if($kind==='admin') {
            $a=$this->Auth_model->attempt_login(trim((string)($p['username']??'')),(string)($p['password']??''));
            if(!$a)throw new Mobile_api_error('Identitas login belum cocok.',401,'INVALID_CREDENTIALS');
            $this->Auth_model->record_login($a['id']);
            return $this->issue('admin',$a['id'],$a['fullname'],$a['role'],$p['device_label']??'');
        }
        return $this->resident_login($kind,$p);
    }
    private function resident_login($kind,$p)
    {
        $code=is_string($p['access_code']??NULL)?trim($p['access_code']):'';
        $phone=Resident_access_model::phone($p['phone']??'');
        if(!in_array($kind,array('resident','payment'),TRUE)||!preg_match('/^[a-f0-9]{64}$/D',$code)||$phone==='')
            throw new Mobile_api_error('Gunakan nomor HP dan kode akses pribadi yang sesuai.',401,'INVALID_CREDENTIALS');
        $this->db->trans_begin();
        try {
            // Serialize token issue against credential rotation, preventing a stale-code race.
            $c=$this->db->query('SELECT * FROM gh_resident_cases WHERE access_hash=? FOR UPDATE',array(hash('sha256',$code)))->row_array();
            if(!$c||!hash_equals(Resident_access_model::phone($c['phone']),$phone))
                throw new Mobile_api_error('Nomor HP atau kode akses tidak cocok.',401,'INVALID_CREDENTIALS');
            if($kind==='payment') {
                $stay=!empty($c['stay_id'])?$this->db->where('id',$c['stay_id'])->where('tenant_id',(int)$c['tenant_id'])->get('gh_tenant_stays')->row_array():NULL;
                if(!$stay)throw new Mobile_api_error('Tagihan akan tersedia setelah reservasi dikonfirmasi.',422,'NOT_READY');
                $result=$this->issue('payment',$stay['id'],$c['full_name'],'payment_viewer',$p['device_label']??'');
            } else $result=$this->issue('resident',$c['id'],$c['full_name'],'resident',$p['device_label']??'');
            if(!$this->db->trans_status())throw new Mobile_api_error('Sesi belum dapat dibuat.',503,'AUTH_BUSY');
            $this->db->trans_commit();return $result;
        } catch(Throwable $e){$this->db->trans_rollback();throw $e;}
    }
    public function intake($p){$this->throttle('intake');if(!$this->Lifecycle_model->ready())throw new Mobile_api_error('Pendaftaran belum tersedia.',503,'NOT_READY');$v=$this->Lifecycle_model->intake($p);$c=$this->Lifecycle_model->get_case($v['id']);return $this->resident_login('resident',array('phone'=>$c['phone'],'access_code'=>$v['code']))+array('access_code'=>$v['code'],'case'=>$c);}
    public function authenticate($header){if(!preg_match('/^Bearer ([a-f0-9]{64})$/D',$header,$m))throw new Mobile_api_error('Token akses diperlukan.',401,'UNAUTHORIZED');$t=$this->db->where('token_hash',hash('sha256',$m[1]))->where('revoked_at',NULL)->where('expires_at >',date('Y-m-d H:i:s'))->get('gh_mobile_tokens')->row_array();if(!$t)throw new Mobile_api_error('Sesi berakhir. Silakan masuk kembali.',401,'TOKEN_EXPIRED');if($t['subject_kind']==='admin'){$a=$this->db->where('id',$t['subject_id'])->where('is_active',1)->get('gh_admin_users')->row_array();if(!$a)throw new Mobile_api_error('Akun tidak aktif.',401,'ACCOUNT_DISABLED');return array('kind'=>'admin','id'=>(int)$a['id'],'name'=>$a['fullname'],'role'=>$a['role'],'token_id'=>$t['id']);}$c=NULL;if($t['subject_kind']==='payment'){$stay=$this->db->where('id',$t['subject_id'])->get('gh_tenant_stays')->row_array();$context=$stay?$this->catalogModel->get_payment_context($stay['tenant_id'],$stay['id']):NULL;if(!$context)throw new Mobile_api_error('Akses pembayaran berakhir.',401,'TOKEN_EXPIRED');return array('kind'=>'payment','id'=>(int)$stay['id'],'tenant_id'=>(int)$stay['tenant_id'],'stay_id'=>(int)$stay['id'],'name'=>$context['fullname']??'Penghuni','role'=>'payment_viewer','token_id'=>$t['id']);}$c=$this->Lifecycle_model->get_case($t['subject_id']);if(!$c)throw new Mobile_api_error('Sesi tidak tersedia.',401,'UNAUTHORIZED');return array('kind'=>'resident','id'=>(int)$c['id'],'name'=>$c['full_name'],'role'=>'resident','token_id'=>$t['id']);}
    public function me($p){return array('user'=>$p,'modules'=>$p['kind']==='admin'?$this->modules($p):array(),'capabilities'=>$p['kind']==='payment'?array('payments_only'):($p['kind']==='resident'?array('portal','payments','files','full_profile','payment_proof','notice','complaints'):array('native_modules','native_files')));}
    public function catalog($part,$id,$body){if($part==='booking'){if(!$this->db->table_exists('gh_booking_requests'))throw new Mobile_api_error('Modul booking belum dimigrasikan.',503,'NOT_READY');$body['fullname']=$body['fullname']??$body['full_name']??'';$body['move_in_plan']=$body['move_in_plan']??$body['planned_start']??'';$body['message']=$body['message']??$body['notes']??'';if(!$this->catalogModel->save_booking_request($body))throw new Mobile_api_error('Lengkapi data booking yang valid.');return array('message'=>'Permintaan survey/booking diterima.');}if($part==='room'){$r=$this->catalogModel->get_room_type_detail($id);if(!$r&&ctype_digit((string)$id)){foreach($this->catalogModel->get_all_public_rooms() as $card)if((int)$card['id']===(int)$id){$r=$this->catalogModel->get_room_type_detail($card['slug']);break;}}if(!$r)throw new Mobile_api_error('Kamar tidak ditemukan.',404,'NOT_FOUND');$photos=$this->catalog_photos($r);return array('room'=>$r,'photos'=>$photos,'gallery'=>$photos);}return array('rooms'=>$this->catalog_cards(),'room_types'=>$this->catalog_cards(),'summary'=>$this->catalogModel->get_summary(),'properties'=>$this->catalogModel->get_property_stats(),'available_rooms'=>$this->Lifecycle_model->rooms(),'intake_rooms'=>$this->Lifecycle_model->rooms(),'house_rules'=>$this->catalogModel->get_house_rules(),'amenities'=>$this->catalogModel->get_amenities(),'cost_items'=>$this->catalogModel->get_cost_items(),'public_info'=>Mobile_public_data::info(),'contacts'=>Mobile_public_data::info()['contacts']);}
    private function catalog_photos($room)
    {
        // Match Landing_model::folder_key: GH 2 -> GH2, PIK 2 -> PIK2.
        $code=strtoupper(preg_replace('/[^a-zA-Z0-9]/','',trim($room['code']??'')));
        $type=strtoupper(preg_replace('/[^a-zA-Z0-9]/','',trim($room['type_name']??'')));
        if(!$code||!$type)return array();
        $out=array();
        foreach($this->catalogModel->get_room_gallery($room) as $photo){
            $raw=$photo['src']??$photo['url']??'';
            $path=is_string($raw)?parse_url($raw,PHP_URL_PATH):NULL;
            if(!is_string($path))continue;
            // Compare path components, never a substring from a query or filename.
            $parts=array_slice(explode('/',rawurldecode($path)),-5);
            if(count($parts)!==5||$parts[0]!=='media'||$parts[1]!=='gallery'
                ||$parts[2]!==$code||$parts[3]!==$type||$parts[4]===''
                ||strpos($parts[4],'\\')!==FALSE||in_array($parts[4],array('.','..'),TRUE))continue;
            $src=Mobile_public_data::media($raw);
            if(!$src)continue;
            $photo['src']=$src;$photo['url']=$src;$out[]=$photo;
        }
        return $out;
    }
    private function catalog_cards(){ $cards=$this->catalogModel->get_all_public_rooms();foreach($cards as &$card){$room=$this->catalogModel->get_room_type_detail($card['slug']??'');$photos=$room?$this->catalog_photos($room):array();$cover=$photos?$photos[0]['src']:NULL;$card['cover_image']=$cover;$card['cover_url']=$cover;$card['image']=$cover;}unset($card);return $cards;}

    private function module_key($key){return $key==='booking'?'bookings':$key;}
    private function allowed($role,$module,$write=FALSE,$action=''){$module=$this->module_key($module);if(in_array($role,array('owner','super_admin','admin'),TRUE))return TRUE;if($role==='manager')return $module!=='users';if($role==='viewer')return !$write&&$module!=='users';if($module==='lifecycle'){if(!$write)return in_array($role,array('finance','maintenance'),TRUE);if(in_array($action,array('verify_payment','refund','resolve_dispute','penalty_payment'),TRUE))return $role==='finance';if(in_array($action,array('inspection_save','inspection_finalize','inspection_extract','maintenance'),TRUE))return $role==='maintenance';return FALSE;}if($module==='payment-proofs')$module='payments';if($role==='finance')return in_array($module,array('dashboard','payments','billing','receivables','deposits','finance','reports'),TRUE);if($role==='maintenance')return in_array($module,array('dashboard','maintenance','inventory','complaints','facilities','housekeeping'),TRUE);return FALSE;}
    private function require_admin($p,$module,$write=FALSE,$action=''){if($p['kind']!=='admin'||!$this->allowed($p['role'],$module,$write,$action))throw new Mobile_api_error('Peran tidak memiliki akses.',403,'FORBIDDEN');}
