    private function options(){$options=array('rooms'=>$this->Operations_model->get_rooms(),'tenants'=>array_map(function($r){return array_intersect_key($r,array_flip(array('id','fullname')));},$this->Operations_model->get_tenants()),'stays'=>$this->Operations_model->get_stay_options(),'contracts'=>$this->Operations_model->get_contract_options(),'periods'=>$this->Master_model->get_billing_periods(),'bills'=>$this->Master_model->get_payment_bill_options(),'properties'=>$this->Master_model->get_active_properties(),'room_types'=>$this->Master_model->get_active_room_types(),'roles'=>array_combine($this->roles,$this->roles));foreach($options as $key=>&$values){if($key==='roles')continue;foreach($values as &$value){$value['label']=trim(($value['fullname']??$value['tenant_name_snapshot']??$value['name']??'').'  -  '.($value['property_code']??$value['code']??'').' '.($value['room_label']??'').' '.($value['period_label']??$value['contract_no']??''));if(trim($value['label'],'  - ')==='')$value['label']='#'.($value['id']??'');}unset($value);}unset($values);return $options;}
