        $config=$this->Operations_model->get_config($this->module_key($key));
        if($config&&$key!=='users'){$config['key']=$key;$config['readonly']=!$this->allowed($role,$key,TRUE)||!empty($config['readonly']);$config['actions']=$this->action_schema($key,$role);unset($config['table']);return $config;}
