    private function action_schema($key,$role){$sets=array('dashboard'=>array(),'properties'=>array('save','delete'),'room-types'=>array('save','delete'),'rooms'=>array('save','delete','toggle-public'),'tenants'=>array('save','end-stay'),'payments'=>array('save-bill','save-payment','delete-payment'),'photos'=>array('upload-slider','upload-room','rotate','delete'),'users'=>array('save','delete'),'booking'=>array('done','status'),'contracts'=>array('save','activate','renew','checkout','cancel','draft'),'billing'=>array('generate'),'deposits'=>array('save'),'receivables'=>array(),'reports'=>array(),'complaints'=>array('save','delete','maintenance'),'payment-proofs'=>array('upload','delete'),'lifecycle'=>array('enroll','reserve','change_room','link_stay','verify_payment','inspection_save','inspection_extract','inspection_finalize','checkin','maintenance','notice','notice_update','overdue_checkout_review','checkout','checkout_overdue','penalty_payment','refund','resolve_dispute'));$out=array();foreach($sets[$key]??array('save','delete') as $action)if($this->allowed($role,$key,TRUE,$action)&&!($key!=='users'&&in_array($action,array('save','delete'),TRUE)&&($this->Operations_model->get_config($this->module_key($key))['readonly']??FALSE)))$out[]=array('key'=>$action,'label'=>$key==='users'&&$action==='delete'?'Nonaktifkan akun':ucwords(str_replace(array('_','-'),' ',$action)),'fields'=>$this->action_fields($key,$action),'scope'=>in_array($action,array('generate','upload-slider','upload-room','enroll','save-bill','save-payment','delete-payment','draft'),TRUE)?'module':'row','method'=>'POST','endpoint'=>'admin/'.$key.'/'.(in_array($action,array('generate','upload-slider','upload-room','enroll','save-bill','save-payment','delete-payment','draft'),TRUE)?'0':'{id}').'/'.$action,'fileFields'=>$this->file_fields($key,$action));return $out;}
    private function action_fields($key,$action){$fields=Mobile_schema::fields($key,$action);if($action==='save'){$config=$this->Operations_model->get_config($this->module_key($key));if($config)$fields=$config['fields'];}if($key==='photos'&&$action==='upload-room'){$fields['property_code']['options']=array();foreach($this->Master_model->get_active_properties() as $r)$fields['property_code']['options'][$r['code']]=$r['code'].'  -  '.$r['name'];$fields['room_type']['options']=array();foreach($this->Master_model->get_active_room_types() as $r)$fields['room_type']['options'][$r['name']]=$r['name'];}return $fields;}
    private function file_fields($key,$action){if($key==='documents')return array('document_file');if($key==='templates')return array('template_file');if($key==='payment-proofs')return array('proof_file');if($key==='photos')return $action==='rotate'?array('rotated_file'):array('photos[]');if($key==='lifecycle')return $action==='enroll'?array('ktp_file','marriage_file'):($action==='inspection_save'?array('scan_file','photo_file'):(in_array($action,array('refund','penalty_payment'),TRUE)?array('proof_file'):array()));return array();}
    public function admin($principal,$parts,$method,$payload,$filters)
    {
        $module=$parts[0]??'modules';if($module==='modules'){$this->require_admin($principal,'dashboard');return array('modules'=>$this->modules($principal));}
        $id=$parts[1]??NULL;$action=$parts[2]??NULL;if($method!=='GET'&&$method!=='POST')throw new Mobile_api_error('Gunakan GET atau POST.',405,'METHOD');
        if($method==='POST'){if($id==='save'||$id==='enroll'||$id==='generate'){$action=$id;$id=0;}if($module==='lifecycle'&&$action==='action')$action=$payload['action']??'';$this->require_admin($principal,$module,TRUE,$action);return $this->write($principal,$module,(int)$id,(string)$action,$payload);}
        $this->require_admin($principal,$module);if($module==='lifecycle'){if(ctype_digit((string)$id)){$d=$this->lifecycle_detail((int)$id,$principal);if($action==='print'){$d['stage']=in_array($filters['stage']??'',array('check_in','routine','check_out'),TRUE)?$filters['stage']:'routine';$d['document_title']='Form Pemeriksaan Fasilitas GulHouse';$d['title']=$d['document_title'];$d['html']=$this->load->view('lifecycle/print',$d,TRUE);}return $d;}$rows=$this->Lifecycle_model->cases();if(in_array($principal['role'],array('finance','maintenance'),TRUE))foreach($rows as &$row){$row['profile_json']=NULL;$row['ktp_file_id']=NULL;$row['marriage_file_id']=NULL;if($principal['role']==='maintenance')$row['phone']='';}unset($row);$query=trim((string)($filters['q']??''));$status=trim((string)($filters['status']??''));$rows=array_values(array_filter($rows,function($r)use($query,$status){return ($status===''||$r['status']===$status)&&($query===''||stripos(($r['full_name']??'').' '.($r['room_label']??'').' '.($r['room_code']??'').' '.($r['phone']??''),$query)!==FALSE);}));$count=count($rows);return array('rows'=>array_slice($rows,max(0,(int)($filters['offset']??0)),max(1,min(500,(int)($filters['limit']??100)))),'schema'=>$this->schema($module,$principal['role']),'options'=>$this->options(),'count'=>$count);}
        if($module==='dashboard'){$this->load->model('Dashboard_model');$period=$this->Dashboard_model->set_period($filters['period']??'');return array('selected_period'=>$period,'summary'=>$this->Dashboard_model->get_summary(),'property_rows'=>$this->Dashboard_model->get_property_rows(),'room_type_rows'=>$this->Dashboard_model->get_room_type_rows(),'charts'=>$this->Dashboard_model->get_charts(),'booking_rows'=>in_array($principal['role'],array('finance','maintenance'),TRUE)?array():$this->Dashboard_model->get_recent_bookings(),'payment_rows'=>$principal['role']==='maintenance'?array():$this->Dashboard_model->get_latest_payment_rows());}
        if($module==='photos')return $this->photos($filters,$principal['role']);
        if($module==='payment-proofs'){$this->load->model('Payment_proof_model');$r=$this->Payment_proof_model->payment((int)$id);if(!$r)throw new Mobile_api_error('Transaksi tidak ditemukan.',404,'NOT_FOUND');return array('record'=>$r,'rows'=>$this->Payment_proof_model->rows((int)$id));}
