    private function tenant_metrics(array $rows)
    {
        // The existing filtered stay rows are complete here, before pagination.
        $metrics=array('tenant_count'=>0,'stay_count'=>count($rows),'active_stays'=>0,'reserved_stays'=>0,'ended_stays'=>0);
        $tenants=array();$statuses=array('active'=>'active_stays','reserved'=>'reserved_stays','ended'=>'ended_stays');
        foreach($rows as $row){
            $tenantId=(int)($row['tenant_id']??0);
            if($tenantId>0)$tenants[$tenantId]=TRUE;
            $status=$row['stay_status']??'';
            if(isset($statuses[$status]))$metrics[$statuses[$status]]++;
        }
        $metrics['tenant_count']=count($tenants);
        return $metrics;
    }
    private function record_actions($module,$record,$actions){return array_values(array_filter($actions,function($action)use($module,$record){$key=$action['key'];$status=$record['status']??'';if($module==='booking'&&(in_array($status,array('converted','done'),TRUE)||!empty($record['archived_at']))&&in_array($key,array('convert','done','status'),TRUE))return FALSE;if($module==='contracts'){if(in_array($key,array('activate','cancel'),TRUE)&&$status!=='draft')return FALSE;if(in_array($key,array('renew','checkout'),TRUE)&&!in_array($status,array('active','expiring'),TRUE))return FALSE;if($key==='checkout'&&!empty($record['lifecycle_case_id']))return FALSE;}return TRUE;}));}
    private function lifecycle_detail($id,$principal){$d=$this->Lifecycle_model->detail($id);if(!$d)throw new Mobile_api_error('Penghuni tidak ditemukan.',404,'NOT_FOUND');$role=$principal['role'];if(in_array($role,array('finance','maintenance'),TRUE)){$d['case']['profile_json']=NULL;$d['case']['profile']=array();$d['case']['ktp_file_id']=NULL;$d['case']['marriage_file_id']=NULL;$deny=$role==='maintenance'?array('ktp','marriage','refund_proof','rent_proof','penalty_proof'):array('ktp','marriage');$d['files']=array_values(array_filter($d['files'],function($f)use($deny){return !in_array($f['kind'],$deny,TRUE);}));}if($role==='maintenance'){$d['payment_summary']=NULL;$d['billing_policy']=array('enabled'=>FALSE);$d['refunds']=array();if($d['checkout']){$d['checkout']['refund_bank']='';$d['checkout']['refund_account']='';}$d['case']['phone']='';}$d['options']=$this->options();if(!in_array($role,array('finance','maintenance'),TRUE)){$d=array_merge($d,$this->Lifecycle_model->administration($d['case']));$d['options']['stays']=$d['link_stays'];}$d['schema']=$this->schema('lifecycle',$principal['role']);$d['actions']=$d['schema']['actions'];return $d;}
    public function resident($p,$part,$method,$payload){if($p['kind']==='payment'&&$part==='payments'&&$method==='GET')return $this->payment_status($p);if($p['kind']!=='resident')throw new Mobile_api_error('Akses penghuni diperlukan.',403,'FORBIDDEN');$c=$this->Lifecycle_model->get_case($p['id']);if($method==='POST'){if($part==='action'){$this->Lifecycle_model->action($c['id'],$payload['action']??'',$payload,'mobile_resident',TRUE);return array('message'=>'Data tersimpan.');}if($part==='complaints'){$s=$this->db->where('id',$c['stay_id'])->get('gh_tenant_stays')->row_array();if(!$s||$s['stay_status']!=='active')throw new Mobile_api_error('Komplain hanya untuk masa tinggal aktif.',403,'FORBIDDEN');if(!$this->catalogModel->submit_resident_complaint(array('tenant_id'=>$c['tenant_id'],'stay_id'=>$c['stay_id'],'room_id'=>$c['room_id'],'stay_status'=>'active'),$payload))throw new Mobile_api_error('Komplain belum tersimpan.');return array('message'=>'Komplain diterima.');}throw new Mobile_api_error('Endpoint tidak ditemukan.',404,'NOT_FOUND');}if($method!=='GET')throw new Mobile_api_error('Gunakan GET atau POST.',405,'METHOD');$d=$this->Lifecycle_model->detail($c['id']);$d['inspections']=array_values(array_filter($d['inspections'],function($i){return $i['status']==='final';}));$ids=array_column($d['inspections'],'id');$d['files']=array_values(array_filter($d['files'],function($f)use($ids){return !$f['inspection_id']||in_array($f['inspection_id'],$ids);}));foreach($d['inspections'] as &$i)unset($i['ocr'],$i['ocr_json']);unset($i);$d['bills']=$c['stay_id']?$this->db->select('b.*,p.period_key')->from('gh_room_bills b')->join('gh_billing_periods p','p.id=b.period_id')->where('b.stay_id',$c['stay_id'])->order_by('p.period_key','DESC')->get()->result_array():array();$d['payments']=$c['stay_id']?$this->db->select('pay.*')->from('gh_payments pay')->join('gh_room_bills b','b.id=pay.room_bill_id')->where('b.stay_id',$c['stay_id'])->get()->result_array():array();return $part==='payme