        elseif($module==='payment-proofs'&&in_array($action,array('upload','delete'),TRUE)){$target='PaymentProofs';$method=$action;$args=array($id);$this->load->model('Payment_proof_model');if($action==='upload'&&!$this->Payment_proof_model->payment($id))throw new Mobile_api_error('Transaksi tidak ditemukan.',404,'NOT_FOUND');if($action==='delete'&&!$this->Payment_proof_model->proof($id))throw new Mobile_api_error('Bukti tidak ditemukan.',404,'NOT_FOUND');}
