    private function photos($f,$role){$root=dirname(dirname(dirname(__DIR__))).'/uploads';$rows=array();foreach(new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS)) as $file){if(!$file->isFile()||!preg_match('/\.(jpg|jpeg|png|webp)$/i',$file->getFilename()))continue;$rel=str_replace('\\','/',substr($file->getPathname(),strlen($root)+1));$parts=explode('/',$rel);if(count($parts)<2||strtoupper($parts[0])==='DOCUMENTS'||($parts[0]!=='SLIDER'&&count($parts)!==3))continue;$scope=$parts[0]==='SLIDER'?'slider':'room';$rows[]=array('id'=>hash('sha256',$rel),'file'=>$file->getFilename(),'filename'=>$file->getFilename(),'scope'=>$scope,'property'=>$scope==='slider'?'':$parts[0],'type'=>$scope==='slider'?'':($parts[1]??''),'file_kind'=>'photo','file_id'=>$file->getFilename(),'url'=>base_url('index.php/api/mobile/files/photo/'.rawurlencode($file->getFilename()).'?'.http_build_query(array('scope'=>$scope,'property'=>$scope==='slider'?'':$parts[0],'type'=>$scope==='slider'?'':($parts[1]??''),'file'=>$file->getFilename()))));}$rows=array_values(array_filter($rows,function($r)use($f){return (empty($f['scope'])||$r['scope']===$f['scope'])&&(empty($f['property'])||$r['property']===$f['property'])&&(empty($f['type'])||$r['type']===$f['type'])&&(empty($f['q'])||stripos($r['filename'],$f['q'])!==FALSE);}));return array('rows'=>array_slice($rows,max(0,(int)($f['offset']??0)),max(1,min(500,(int)($f['limit']??100)))),'count'=>count($rows),'options'=>$this->options(),'schema'=>$this->schema('photos',$role));}
